im","w":12,"kind":"jev","jev":"Is this true? Is the copy free of numbers, percentages and big claims?","pushes":"low","fix":"Add no number; keep it plain."},{"meter":"ease","id":"E12","q":"Does the screen use 2 or fewer typefaces?","yes":"Two typefaces or fewer.","w":8,"kind":"code","jev":"Does the screen use 2 or fewer typefaces?","pushes":null,"fix":"Cut the screen down to two typefaces."},{"meter":"ease","id":"E13","q":"Is the colour palette limited to one or two accent colours on neutrals?","yes":"One or two accent colours.","w":8,"kind":"code","jev":"Is the colour palette limited to one or two accent colours on neutrals?","pushes":null,"fix":"Limit the accents to two colours on neutrals."}]
